            assert(mymap.contains_key(v));
            axiom_multiset_contained(mymap, v);
            assert(mymap[v] > 0);
            assert(Multiset::from_map(mymap).count(v) > 0);
            assert(lhs.contains(v));
        }
    };
    axiom_set_ext_equal(lhs, rhs);
